    (7, 'Acme',   '2026-03-01', NULL, 'sent'),
    (3, 'Birch',  '2026-03-01', NULL, 'sent'),
    (5, 'Cobalt', '2026-02-10', NULL, 'sent'),
    (1, 'Dune',   '2026-03-10', NULL, 'sent'),
    (2, 'Elm',    '2026-02-01', '2026-02-03', 'paid'),
    (4, 'Fjord',  NULL,         NULL, 'sent'),
    (6, 'Grove',  '2026-02-20', NULL, NULL),
    (8, 'Heath',  '2026-02-15', NULL, 'void'),
    (9, 'Iris',   '2026-03-11', NULL, 'sent');
`);
